mapper.select:
WHERE o.status = '待接单' AND o.expect_time > NOW()
AND (o.express_company LIKE CONCAT('%', #{keyword}, '%') OR o.pickup_location LIKE CONCAT('%', #{keyword}, '%') OR o.deliver_location LIKE CONCAT('%', #{keyword}, '%') OR o.remark LIKE CONCAT('%', #{keyword}, '%'))
AND o.reward_amount >= #{minReward}
AND o.reward_amount <= #{maxReward}
ORDER BY o.create_time DESC


WHERE


        o.publisher_id = #{publisherId}


        o.taker_id = #{takerId}



    AND o.status IN


            '待接单','已接单','取件中','配送中','待收货'
            '已完成','已取消'
            #{group}



ORDER BY o.create_time DESC

WHERE o.transfer_status = '待接力' AND o.status IN ('已接单', '取件中') AND o.expect_time > NOW()
AND (o.express_company LIKE CONCAT('%', #{keyword}, '%') OR o.pickup_location LIKE CONCAT('%', #{keyword}, '%') OR o.deliver_location LIKE CONCAT('%', #{keyword}, '%') OR o.remark LIKE CONCAT('%', #{keyword}, '%'))
AND o.reward_amount >= #{minReward}
AND o.reward_amount <= #{maxReward}
ORDER BY o.update_time DESC

SELECT COALESCE(SUM(reward_amount), 0)
FROM t_order
WHERE taker_id = #{takerId}
  AND status = #{status}

SELECT COALESCE(SUM(reward_amount), 0)
FROM t_order
WHERE publisher_id = #{publisherId}
  AND status = #{status}
